mapper.delete:
DELETE FROM member
WHERE member_status = 'DELETED'
  AND deleted_at <= #{cutoffDate}

mapper.update:
UPDATE member
SET last_login_at = NOW()
WHERE member_id = #{memberId}

UPDATE member
SET member_status = 'DORMANT'
WHERE member_id IN (
    SELECT temp.member_id FROM (
       SELECT member_id
       FROM member
       WHERE member_status = 'ACTIVE'
         AND (
           last_login_at < #{cutoffDate}
               OR (last_login_at IS NULL AND created_at < #{cutoffDate})
           )
   ) AS temp
)
